"""uuid ids generated by postgres

Revision ID: 67f76ee220b7
Revises: c87b465d9538
Create Date: 2026-09-04 15:20:00.000000

The ids were 32-char hex strings built in Python. They become native `uuid`
columns filled by Postgres 18's `uuidv7()`. Existing values survive: a 32-digit
hex string casts to uuid unchanged, only its text form gains dashes.

Foreign keys have to be dropped before the referenced type changes and rebuilt
afterwards — Postgres refuses to alter a column a constraint depends on.
"""
from typing import Sequence, Union

from alembic import op


# revision identifiers, used by Alembic.
revision: str = '67f76ee220b7'
down_revision: Union[str, Sequence[str], None] = 'c87b465d9538'
branch_labels: Union[str, Sequence[str], None] = None
depends_on: Union[str, Sequence[str], None] = None

# (constraint, table, columns, referenced table, referenced columns, on delete)
_FOREIGN_KEYS = [
    ("games_owner_user_id_fkey", "games", ["owner_user_id"], "users", ["id"], None),
    ("players_user_id_fkey", "players", ["user_id"], "users", ["id"], None),
    ("players_owner_user_id_fkey", "players", ["owner_user_id"], "users", ["id"], None),
    ("game_players_game_id_fkey", "game_players", ["game_id"], "games", ["id"], "CASCADE"),
    ("game_players_player_id_fkey", "game_players", ["player_id"], "players", ["id"], None),
    ("turns_game_id_fkey", "turns", ["game_id"], "games", ["id"], "CASCADE"),
    (
        "darts_game_id_turn_index_fkey",
        "darts",
        ["game_id", "turn_index"],
        "turns",
        ["game_id", "turn_index"],
        "CASCADE",
    ),
]

# (table, column)
_ID_COLUMNS = [
    ("users", "id"),
    ("games", "id"),
    ("games", "owner_user_id"),
    ("players", "id"),
    ("players", "user_id"),
    ("players", "owner_user_id"),
    ("game_players", "game_id"),
    ("game_players", "player_id"),
    ("turns", "game_id"),
    ("darts", "game_id"),
]

_GENERATED = [("users", "id"), ("games", "id"), ("players", "id")]


def _drop_foreign_keys() -> None:
    for name, table, *_ in _FOREIGN_KEYS:
        op.drop_constraint(name, table, type_="foreignkey")


def _create_foreign_keys() -> None:
    for name, table, columns, target, target_columns, ondelete in _FOREIGN_KEYS:
        op.create_foreign_key(name, table, target, columns, target_columns, ondelete=ondelete)


def upgrade() -> None:
    """Upgrade schema."""
    _drop_foreign_keys()

    for table, column in _ID_COLUMNS:
        op.execute(
            f'ALTER TABLE {table} ALTER COLUMN {column} TYPE uuid USING {column}::uuid'
        )

    for table, column in _GENERATED:
        op.execute(f'ALTER TABLE {table} ALTER COLUMN {column} SET DEFAULT uuidv7()')

    _create_foreign_keys()


def downgrade() -> None:
    """Downgrade schema."""
    _drop_foreign_keys()

    for table, column in _GENERATED:
        op.execute(f'ALTER TABLE {table} ALTER COLUMN {column} DROP DEFAULT')

    # Back to the 32-char hex form the application used to generate.
    for table, column in _ID_COLUMNS:
        op.execute(
            f'ALTER TABLE {table} ALTER COLUMN {column} TYPE VARCHAR(32) '
            f"USING replace({column}::text, '-', '')"
        )

    _create_foreign_keys()
